"""Permission API endpoints"""
from fastapi import APIRouter, Depends, HTTPException, Query
from typing import Optional, List
from sqlalchemy.orm import Session

from app.deps import DBSession, CurrentActiveUser
from app.models.user import User
from app.models.permission import DocumentPermission
from app.models.document import Document

router = APIRouter(prefix="/permissions", tags=["permissions"])


class PermissionGrantRequest:
    """Permission grant request schema"""
    def __init__(self, document_id: int, user_id: Optional[int] = None, permission_level: str = "read"):
        self.document_id = document_id
        self.user_id = user_id
        self.permission_level = permission_level


@router.post("", status_code=201)
def grant_permission(
    document_id: int,
    target_user_id: Optional[int] = None,
    permission_level: str = Query("read", pattern="^(read|write|admin)$"),
    user: User = CurrentActiveUser,
    db: Session = DBSession
):
    """Grant permission to a document."""
    document = db.query(Document).filter(Document.id == document_id).first()
    if not document:
        raise HTTPException(status_code=404, detail="Document not found")

    if user.role != "admin" and document.created_by != user.id:
        raise HTTPException(status_code=403, detail="Only document owner or admin can grant permissions")

    if target_user_id:
        existing = db.query(DocumentPermission).filter(
            DocumentPermission.document_id == document_id,
            DocumentPermission.user_id == target_user_id
        ).first()
        if existing:
            existing.permission_level = permission_level
            db.commit()
            return {"message": "Permission updated", "permission": existing.id}

        permission = DocumentPermission(
            document_id=document_id,
            user_id=target_user_id,
            permission_level=permission_level,
            granted_by=user.id
        )
        db.add(permission)
        db.commit()
        return {"message": "Permission granted", "permission": permission.id}

    return {"message": "Public access permission not implemented"}


@router.delete("/{permission_id}", status_code=204)
def revoke_permission(
    permission_id: int,
    user: User = CurrentActiveUser,
    db: Session = DBSession
):
    """Revoke a permission."""
    permission = db.query(DocumentPermission).filter(DocumentPermission.id == permission_id).first()
    if not permission:
        raise HTTPException(status_code=404, detail="Permission not found")

    document = db.query(Document).filter(Document.id == permission.document_id).first()
    if user.role != "admin" and document.created_by != user.id:
        raise HTTPException(status_code=403, detail="Only document owner or admin can revoke permissions")

    db.delete(permission)
    db.commit()
    return None


@router.get("")
def list_permissions(
    document_id: Optional[int] = None,
    user: User = CurrentActiveUser,
    db: Session = DBSession
):
    """List permissions for documents."""
    if document_id:
        document = db.query(Document).filter(Document.id == document_id).first()
        if not document:
            raise HTTPException(status_code=404, detail="Document not found")
        if user.role != "admin" and document.created_by != user.id:
            raise HTTPException(status_code=403, detail="Access denied")

        permissions = db.query(DocumentPermission).filter(
            DocumentPermission.document_id == document_id
        ).all()
    else:
        if user.role != "admin":
            documents = db.query(Document).filter(Document.created_by == user.id).all()
            doc_ids = [d.id for d in documents]
            permissions = db.query(DocumentPermission).filter(
                DocumentPermission.document_id.in_(doc_ids)
            ).all()
        else:
            permissions = db.query(DocumentPermission).all()

    return [
        {
            "id": p.id,
            "document_id": p.document_id,
            "user_id": p.user_id,
            "permission_level": p.permission_level,
            "granted_by": p.granted_by,
            "created_at": p.created_at.isoformat() if p.created_at else None
        }
        for p in permissions
    ]

"""Authentication service"""
from datetime import timedelta
from typing import Optional
from fastapi import HTTPException, status
from sqlalchemy.orm import Session

from app.core.security import (
    verify_password,
    get_password_hash,
    create_access_token,
    get_current_user_id,
    oauth2_scheme,
)
from app.models.user import User
from app.schemas.user import UserCreate, UserResponse
from app.schemas.token import Token
from app.config import settings


class AuthService:
    """Authentication service for user management and token operations"""

    @staticmethod
    def authenticate_user(db: Session, username: str, password: str) -> Optional[User]:
        """Authenticate user with username and password."""
        user = db.query(User).filter(User.username == username).first()
        if not user:
            return None
        if not verify_password(password, user.password_hash):
            return None
        return user

    @staticmethod
    def create_user(db: Session, user_data: UserCreate) -> User:
        """Create a new user."""
        existing_user = db.query(User).filter(User.username == user_data.username).first()
        if existing_user:
            raise HTTPException(
                status_code=status.HTTP_400_BAD_REQUEST,
                detail="Username already exists",
            )

        if user_data.email:
            existing_email = db.query(User).filter(User.email == user_data.email).first()
            if existing_email:
                raise HTTPException(
                    status_code=status.HTTP_400_BAD_REQUEST,
                    detail="Email already registered",
                )

        hashed_password = get_password_hash(user_data.password)
        db_user = User(
            username=user_data.username,
            email=user_data.email or None,
            password_hash=hashed_password,
            role="user",
        )
        db.add(db_user)
        db.commit()
        db.refresh(db_user)
        return db_user

    @staticmethod
    def login(db: Session, username: str, password: str) -> Token:
        """Login and return access token."""
        user = AuthService.authenticate_user(db, username, password)
        if not user:
            raise HTTPException(
                status_code=status.HTTP_401_UNAUTHORIZED,
                detail="Incorrect username or password",
                headers={"WWW-Authenticate": "Bearer"},
            )

        if not user.is_active:
            raise HTTPException(
                status_code=status.HTTP_403_FORBIDDEN,
                detail="User account is disabled",
            )

        user.last_login = None
        db.commit()

        access_token = create_access_token(
            data={"sub": str(user.id), "username": user.username, "role": user.role},
            expires_delta=timedelta(minutes=settings.ACCESS_TOKEN_EXPIRE_MINUTES),
        )

        return Token(
            access_token=access_token,
            token_type="bearer",
            expires_in=settings.ACCESS_TOKEN_EXPIRE_MINUTES * 60,
        )

    @staticmethod
    def get_current_user(db: Session, token: str) -> User:
        """Get current user from token."""
        user_id = get_current_user_id(token)
        user = db.query(User).filter(User.id == user_id).first()
        if not user:
            raise HTTPException(
                status_code=status.HTTP_401_UNAUTHORIZED,
                detail="User not found",
            )
        if not user.is_active:
            raise HTTPException(
                status_code=status.HTTP_403_FORBIDDEN,
                detail="User account is disabled",
            )
        return user

"""Security utilities for JWT and password handling"""
from datetime import datetime, timedelta, UTC
from typing import Optional
from jose import JWTError, jwt
from passlib.context import CryptContext
from fastapi import HTTPException, status
from fastapi.security import OAuth2PasswordBearer

from app.config import settings

pwd_context = CryptContext(schemes=["bcrypt"], deprecated="auto")
oauth2_scheme = OAuth2PasswordBearer(tokenUrl="/api/v1/auth/login")


def verify_password(plain_password: str, hashed_password: str) -> bool:
    """Verify a plain password against a hashed password."""
    return pwd_context.verify(plain_password, hashed_password)


def get_password_hash(password: str) -> str:
    """Hash a plain password."""
    return pwd_context.hash(password)


def create_access_token(data: dict, expires_delta: Optional[timedelta] = None) -> str:
    """Create a JWT access token."""
    to_encode = data.copy()
    if expires_delta:
        expire = datetime.now(UTC) + expires_delta
    else:
        expire = datetime.now(UTC) + timedelta(minutes=settings.ACCESS_TOKEN_EXPIRE_MINUTES)
    to_encode.update({"exp": expire})
    encoded_jwt = jwt.encode(to_encode, settings.SECRET_KEY, algorithm=settings.ALGORITHM)
    return encoded_jwt


def decode_token(token: str) -> dict:
    """Decode and verify a JWT token."""
    try:
        payload = jwt.decode(token, settings.SECRET_KEY, algorithms=[settings.ALGORITHM])
        return payload
    except JWTError:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Could not validate credentials",
            headers={"WWW-Authenticate": "Bearer"},
        )


def get_current_user_id(token: str) -> int:
    """Extract user_id from token."""
    payload = decode_token(token)
    user_id = payload.get("sub")
    if user_id is None:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Could not validate credentials",
            headers={"WWW-Authenticate": "Bearer"},
        )
    return int(user_id)

"""Custom exceptions"""


class NotFoundError(Exception):
    """Resource not found."""

    def __init__(self, resource: str, resource_id: int):
        self.resource = resource
        self.resource_id = resource_id
        super().__init__(f"{resource} with id {resource_id} not found")


class ValidationError(Exception):
    """Validation error."""

    def __init__(self, message: str):
        self.message = message
        super().__init__(message)


class UnsupportedFileTypeError(Exception):
    """Unsupported file type."""

    def __init__(self, file_type: str):
        self.file_type = file_type
        super().__init__(f"Unsupported file type: {file_type}")


class PermissionDeniedError(Exception):
    """Permission denied."""

    def __init__(self, message: str = "Permission denied"):
        self.message = message
        super().__init__(message)

